fam:=CASE WHEN sess='regular' THEN 'P01' ELSE 'P02' END;
tid:=gen_random_uuid();aid:=gen_random_uuid();tok:=gen_random_uuid()::text;
SELECT count(*),encode(sha256(convert_to(string_agg(encode(sha256(convert_to(jsonb_build_array(b.instrument_key,extract(epoch FROM b.bar_ts),b.session_label::text,encode(float8send(b.open),'hex'),encode(float8send(b.high),'hex'),encode(float8send(b.low),'hex'),encode(float8send(b.close),'hex'),b.volume,b.trade_count,encode(float8send(b.vwap),'hex'),b.loaded_by_job_id,extract(epoch FROM b.source_loaded_at))::text,'UTF8')),'hex'),chr(10) ORDER BY b.bar_ts),'UTF8')),'hex')
INTO nr,ch FROM market_fixed_20250901_20260831.alpaca_sip_bars_1m_202608 b WHERE b.instrument_key=7751 AND b.bar_ts>='2026-08-03T04:00Z' AND b.bar_ts<'2026-08-04T04:00Z' AND b.session_label::text=sess;
ft:=base_t;ft.task_id:=tid;ft.family_id:=fam;ft.partition_key:='test-norm4:'||tid;ft.operation_key:=ft.partition_key;ft.status:='LEASED';ft.attempt_id:=aid;ft.lease_until:=clock_timestamp()+interval '2 minutes';ft.blocker_code:=NULL;ft.resumption_condition:=NULL;
ft.payload:=ft.payload||jsonb_build_object('kind','RETAINED_ALPACA_AUGUST_ALL_SESSIONS_V4','session_label',sess);
ft.input_versions:=ft.input_versions||jsonb_build_object('manifest_sha256',ch);
INSERT INTO population_top3000_202608_202609_v1.pipeline_task SELECT ft.*;
fm:=base_m;fm.manifest_id:=ft.partition_key;fm.partition_key:=ft.partition_key;fm.family_id:=fam;fm.session_label:=sess;fm.observed_rows:=nr;fm.source_content_sha256:=ch;fm.manifest_sha256:=ch;fm.input_versions:=ft.input_versions;fm.created_by_task:=tid;
INSERT INTO population_top3000_202608_202609_v1.retained_price_partition_v1 SELECT fm.*;
INSERT INTO population_top3000_202608_202609_v1.pipeline_attempt(attempt_id,task_id,execution_number,token_sha256,owner_fence,stop_generation,adapter_sha256) VALUES(aid,tid,1,encode(sha256(convert_to(tok,'UTF8')),'hex'),3,1,h);

r:=population_top3000_202608_202609_v1.retained_price_normalize_v4(aid,tok);
IF r->>'state' IS DISTINCT FROM 'COMPLETE' THEN RAISE EXCEPTION 'SETUP_FAILED'; END IF;
UPDATE population_top3000_202608_202609_v1.retained_price_observation_v2 SET vwap=vwap+0.01 WHERE manifest_id=fm.manifest_id AND bar_ts=(SELECT min(bar_ts) FROM population_top3000_202608_202609_v1.retained_price_observation_v2 WHERE manifest_id=fm.manifest_id);
r:=population_top3000_202608_202609_v1.retained_price_normalize_v4(aid,tok);
INSERT INTO review_proof SELECT jsonb_build_object('test','persisted_numeric_mutation_on_idempotent_retry','returned_state',r->>'state','new_committed_units',r#>>'{commit_receipt,new_committed_units}','mismatched_vwap_rows',count(*),'candidate_sha256',h,'production_accepted',false) FROM population_top3000_202608_202609_v1.retained_price_observation_v2 o JOIN market_fixed_20250901_20260831.alpaca_sip_bars_1m_202608 b ON b.instrument_key=o.instrument_key AND b.bar_ts=o.bar_ts WHERE o.manifest_id=fm.manifest_id AND float8send(o.vwap) IS DISTINCT FROM float8send(b.vwap);
END LOOP;
END $test$;
SELECT * FROM review_proof;

